import { OrderRepository } from '../../domain/order/OrderRepository';
import { OrderStatus } from '../../domain/order/OrderStatus';
import { OrderDto, toOrderDto } from '../dto/OrderDto';

export class ListOrdersUseCase {
  constructor(private readonly orders: OrderRepository) {}

  /** Lists every order, or only those in the given state. */
  execute(status?: OrderStatus): OrderDto[] {
    const orders = status ? this.orders.findByStatus(status) : this.orders.findAll();
    return orders.map(toOrderDto);
  }
}

